CREATE TABLE leads ( id BIGSERIAL PRIMARY KEY, nome VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL, telefone VARCHAR(30) NOT NULL, passeio VARCHAR(120) NOT NULL, data_passeio DATE NULL, quantidade_pessoas INTEGER NOT NULL CHECK (quantidade_pessoas BETWEEN 1 AND 100), consentimento_lgpd BOOLEAN NOT NULL CHECK (consentimento_lgpd = TRUE), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() ); CREATE INDEX idx_leads_created_at ON leads(created_at DESC);